#include <string>
#include <sstream>

class Solution {
public:
    int countValidWords(std::string sentence) {
        auto isValid = [](const std::string& token) -> bool {
            if (token.empty()) return false;
            int hyphenCount = 0;
            int n = token.size();
            for (int i = 0; i < n; ++i) {
                char ch = token[i];
                if (std::isdigit(ch)) return false;
                if (ch == '-') {
                    hyphenCount++;
                    if (hyphenCount > 1) return false;
                    if (i == 0 || i == n - 1) return false;
                    if (!std::isalpha(token[i - 1]) || !std::isalpha(token[i + 1])) return false;
                } else if (ch == '!' || ch == '.' || ch == ',') {
                    if (i != n - 1) return false;
                }
            }
            return true;
        };

        std::stringstream ss(sentence);
        std::string token;
        int count = 0;
        while (ss >> token) {
            if (isValid(token)) count++;
        }
        return count;
    }
};

class Solution {
    public int countValidWords(String sentence) {
        int count = 0;
        for (String token : sentence.trim().split("\\s+")) {
            if (isValid(token)) count++;
        }
        return count;
    }

    private boolean isValid(String token) {
        if (token.isEmpty()) return false;
        int hyphenCount = 0;
        int n = token.length();
        for (int i = 0; i < n; i++) {
            char ch = token.charAt(i);
            if (Character.isDigit(ch)) return false;
            if (ch == '-') {
                hyphenCount++;
                if (hyphenCount > 1) return false;
                if (i == 0 || i == n - 1) return false;
                if (!Character.isLetter(token.charAt(i - 1)) || !Character.isLetter(token.charAt(i + 1))) return false;
            } else if (ch == '!' || ch == '.' || ch == ',') {
                if (i != n - 1) return false;
            }
        }
        return true;
    }
}

